#!/usr/bin/env bash
set -euo pipefail

usage() {
    echo "Usage: ddcast {on|off|status}" >&2
    exit 1
}

[ $# -eq 1 ] || usage

case "$1" in
    on)
        systemctl --user start ddcast
        ;;
    off)
        systemctl --user stop ddcast
        ;;
    status)
        systemctl --user status ddcast --no-pager
        ;;
    *)
        usage
        ;;
esac

